using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using ResearchAgent;

var builder = Host.CreateApplicationBuilder(args);

builder.Services.AddChatClient(chatClientBuilder => chatClientBuilder
    .UseOpenAIChatClient(
        builder.Configuration["AI:Model"] ?? "gpt-4o-mini-2024-07-18",
        builder.Configuration["AI:ApiKey"]
            ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
            ?? throw new InvalidOperationException(
                "Set AI:ApiKey in configuration or OPENAI_API_KEY environment variable.")));

builder.Services.AddSingleton<Notepad>();
builder.Services.AddSingleton<ResearchTools>();

using var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var researchTools = host.Services.GetRequiredService<ResearchTools>();

var agent = new ChatClientAgent(
    chatClient,
    new ChatClientAgentOptions
    {
        Name = "ResearchAgent",
        Description = "An AI agent that researches topics by searching the web and taking notes.",
        ChatOptions = new ChatOptions
        {
            Temperature = 0f,
            MaxOutputTokens = 4096,
            Tools = researchTools.GetTools(),
        },
    });

var topic = args.Length > 0
    ? string.Join(' ', args)
    : "the latest advances in quantum computing in 2026";

Console.WriteLine($"🔍 Researching: {topic}");
Console.WriteLine(new string('─', 60));

var prompt = $"""
    Research the following topic thoroughly: "{topic}"

    Instructions:
    1. Use the web_search tool multiple times with different queries to gather information.
    2. Use the take_note tool to record important findings as you discover them.
    3. After gathering enough information, use the get_notes tool to review all your notes.
    4. Provide a comprehensive summary of your research findings.

    Be thorough and search from multiple angles to get a well-rounded understanding.
    """;

var session = await agent.CreateSessionAsync(cancellationToken: CancellationToken.None);
var response = await agent.RunAsync(prompt, session);

Console.WriteLine();
Console.WriteLine("📋 Research Summary");
Console.WriteLine(new string('─', 60));
Console.WriteLine(response.Messages.Last().Text);
Console.WriteLine();

var notepad = host.Services.GetRequiredService<Notepad>();
if (notepad.Notes.Count > 0)
{
    Console.WriteLine($"📝 Notes collected: {notepad.Notes.Count}");
    foreach (var note in notepad.Notes)
    {
        Console.WriteLine($"  • {note}");
    }
}

