+/// </summary>
+public sealed class ResearchTools
+{
+    private readonly Notepad _notepad;
+    private readonly HttpClient _httpClient;
+    private readonly string? _searchApiKey;
+
+    public ResearchTools(Notepad notepad, IConfiguration configuration)
+    {
+        _notepad = notepad;
+        _httpClient = new HttpClient();
+        _searchApiKey = configuration["Search:ApiKey"]
+            ?? Environment.GetEnvironmentVariable("SEARCH_API_KEY");
+    }
+
+    public IList<AITool> GetTools() =>
+    [
+        AIFunctionFactory.Create(WebSearchAsync),
+        AIFunctionFactory.Create(TakeNote),
+        AIFunctionFactory.Create(GetNotes),
+    ];
+
+    [Description("Search the web for information on a given query. Returns relevant search results with titles, snippets, and URLs.")]
+    private async Task<string> WebSearchAsync(
+        [Description("The search query to look up")] string query,
+        CancellationToken cancellationToken = default)
+    {
+        Console.WriteLine($"  🌐 Searching: \"{query}\"");
+
+        if (!string.IsNullOrEmpty(_searchApiKey))
+        {
+            return await ExecuteRealSearchAsync(query, cancellationToken);
+        }
+
+        // Simulated search results when no API key is configured
+        return GenerateSimulatedResults(query);
+    }
+
+    [Description("Take a note to record an important finding during research. Use this to save key facts, statistics, or insights.")]
+    private string TakeNote(
+        [Description("The note content to save")] string note)
+    {
+        _notepad.AddNote(note);
+        Console.WriteLine($"  📝 Note taken: \"{Truncate(note, 60)}\"");
+        return $"Note saved successfully. Total notes: {_notepad.Notes.Count}";
+    }
+
+    [Description("Retrieve all notes taken during the research session.")]
+    private string GetNotes()
+    {
+        Console.WriteLine($"  📋 Retrieving {_notepad.Notes.Count} notes");
+        return _notepad.GetAllNotes();
+    }
+
+    private async Task<string> ExecuteRealSearchAsync(string query, CancellationToken cancellationToken)
+    {
+        // Uses Bing Web Search API v7 — set SEARCH_API_KEY to your Bing Search key
+        var requestUri = $"https://api.bing.microsoft.com/v7.0/search?q={Uri.EscapeDataString(query)}&count=5";
+        using var request = new HttpRequestMessage(HttpMethod.Get, requestUri);
+        request.Headers.Add("Ocp-Apim-Subscription-Key", _searchApiKey);
+
+        try
+        {
+            using var response = await _httpClient.SendAsync(request, cancellationToken);
+            response.EnsureSuccessStatusCode();
+
+            var json = await response.Content.ReadFromJsonAsync<JsonElement>(cancellationToken);
+            var results = new List<string>();
+
+            if (json.TryGetProperty("webPages", out var webPages) &&
+                webPages.TryGetProperty("value", out var values))
+            {
+                foreach (var item in values.EnumerateArray().Take(5))
+                {
+                    var title = item.GetProperty("name").GetString();
+                    var snippet = item.GetProperty("snippet").GetString();
+                    var url = item.GetProperty("url").GetString();
+                    results.Add($"Title: {title}\nSnippet: {snippet}\nURL: {url}");
+                }
+            }
+
+            return results.Count > 0
+                ? string.Join("\n\n---\n\n", results)
+                : "No results found.";
+        }
+        catch (HttpRequestException ex)
+        {
+            return $"Search failed: {ex.Message}. Falling back to simulated results.\n\n{GenerateSimulatedResults(query)}";
+        }
+    }
+
+    private static string GenerateSimulatedResults(string query)
+    {
+        return $"""
+            Search results for: "{query}"
+
+            1. Title: Overview of {query}
+               Snippet: This comprehensive article covers the latest developments and key aspects of {query}, including recent breakthroughs and expert analysis.
+               URL: https://example.com/articles/{Uri.EscapeDataString(query)}
+
+            2. Title: Recent Research on {query}
+               Snippet: Academic researchers have published new findings related to {query}, highlighting significant progress in the field.
+               URL: https://example.com/research/{Uri.EscapeDataString(query)}
+
+            3. Title: Expert Analysis: {query}
+               Snippet: Industry experts weigh in on the current state and future direction of {query}, noting key trends and potential impacts.
+               URL: https://example.com/analysis/{Uri.EscapeDataString(query)}
+
+            Note: These are simulated results. Set SEARCH_API_KEY to a Bing Search API key for real web searches.
+            """;
+    }
+
+    private static string Truncate(string text, int maxLength) =>
+        text.Length <= maxLength ? text : text[..(maxLength - 3)] + "...";
+}
+

