namespace ResearchAgent;

/// <summary>
/// Simple in-memory notepad for the research agent to store findings.
/// </summary>
public sealed class Notepad
{
    private readonly List<string> _notes = [];

    public IReadOnlyList<string> Notes => _notes;

    public void AddNote(string note)
    {
        _notes.Add(note);
    }

    public string GetAllNotes()
    {
        if (_notes.Count == 0)
        {
            return "No notes have been taken yet.";
        }

        return string.Join(Environment.NewLine, _notes.Select((n, i) => $"{i + 1}. {n}"));
    }
}

